dashboard.definition:
{
  "title": "AD Replication & Sync Health",
  "description": "State of Active Directory replication between domain controllers: per-link status (last success, lag, last result) from MSAD:NT6:Replication, replication-related Directory Service and DFSR events (KCC, lingering objects, tombstone lifetime, DNS failures, USN rollback), sync start/end audit events, and Kerberos clock-skew failures.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@h,now"
      }
    }
  },
  "defaults": {},
  "visualizations": {
    "viz_1": {
      "type": "splunk.singlevalue",
      "title": "DCs reporting replication status",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "title": "Failing replication links",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "title": "Max time since last success (min)",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 60
          },
          {
            "value": "#FFC300",
            "from": 60,
            "to": 240
          },
          {
            "value": "#B0413E",
            "from": 240
          }
        ]
      }
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "title": "Replication error events",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 10
          },
          {
            "value": "#B0413E",
            "from": 10
          }
        ]
      }
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "title": "Critical events (lingering objects, tombstone, USN rollback)",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "title": "Minutes since last replication event",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 30
          },
          {
            "value": "#B0413E",
            "from": 30
          }
        ]
      }
    },
    "viz_7": {
      "type": "splunk.table",
      "title": "Replication links - current state",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "count": 15,
        "wrap": true,
        "columnFormat": {
          "status": {
            "rowBackgroundColors": "> table | seriesByName(\"status\") | matchValue(statusColorConfig)"
          }
        }
      },
      "description": "dc = DC that receives the changes, partner = replication source (src_host). Source: MSAD:NT6:Replication (LastSuccessfulSync / LastAttemptedSync / Result; Result 0 = success). LATE = no successful sync for more than 4 hours.",
      "context": {
        "statusColorConfig": [
          {
            "match": "OK",
            "value": "#65A637"
          },
          {
            "match": "LATE",
            "value": "#F8BE34"
          },
          {
            "match": "FAILING",
            "value": "#B0413E"
          }
        ]
      }
    },
    "viz_8": {
      "type": "splunk.column",
      "title": "Failed replication events by DC",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      }
    },
    "viz_9": {
      "type": "splunk.column",
      "title": "Replication-related events over time",
      "dataSources": {
        "primary": "ds_9"
      },
      "options": {
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      }
    },
    "viz_10": {
      "type": "splunk.table",
      "title": "Directory Service / DFSR replication events",
      "dataSources": {
        "primary": "ds_10"
      },
      "options": {
        "count": 10,
        "wrap": true,
        "columnFormat": {
          "severity": {
            "rowBackgroundColors": "> table | seriesByName(\"severity\") | matchValue(severityColorConfig)"
          }
        }
      },
      "context": {
        "severityColorConfig": [
          {
            "match": "critical",
            "value": "#B0413E"
          },
          {
            "match": "high",
            "value": "#F1813F"
          },
          {
            "match": "medium",
            "value": "#F8BE34"
          }
        ]
      }
    },
    "viz_11": {
      "type": "splunk.table",
      "title": "Replication errors by DC and event",
      "dataSources": {
        "primary": "ds_11"
      },
      "options": {
        "count": 10,
        "wrap": true
      }
    },
    "viz_12": {
      "type": "splunk.table",
      "title": "Security 4932/4933: replica sync start/end",
      "dataSources": {
        "primary": "ds_12"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "description": "Requires the audit policy \"Audit Detailed Directory Service Replication\" (Security events 4932/4933)."
    },
    "viz_13": {
      "type": "splunk.table",
      "title": "Kerberos clock-skew failures (event 4771, code 0x25) - time sync",
      "dataSources": {
        "primary": "ds_13"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "description": "Clients whose clock drifts more than 5 minutes from the DC: a typical side effect of broken AD time synchronisation."
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "DCs reporting replication status",
      "options": {
        "query": "`adx_repl_data` | stats dc(host)",
        "queryParameters": {
          "earliest": "-30m",
          "latest": "now"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Failing replication links",
      "options": {
        "query": "`adx_repl_links` | where last_result!=\"0\" | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Max time since last success (min)",
      "options": {
        "query": "`adx_repl_links` | stats max(lag_min)",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Replication error events",
      "options": {
        "query": "`adx_ds_events` EventCode IN (1308,1311,1388,1566,1865,1925,1988,2042,2087,2088,2095,2213,4012) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Critical events (lingering objects, tombstone, USN rollback)",
      "options": {
        "query": "`adx_ds_events` EventCode IN (1388,1988,2042,2095,4012) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Minutes since last replication event",
      "options": {
        "query": "`adx_repl_data` | stats max(_time) as t | eval m=round((now()-t)/60,0) | fields m",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Replication links - current state",
      "options": {
        "query": "`adx_repl_links` | eval last_success=strftime(last_success_epoch,\"%Y-%m-%d %H:%M\"), last_attempt=strftime(last_attempt_epoch,\"%Y-%m-%d %H:%M\"), status=case(last_result!=\"0\",\"FAILING\", lag_min>240,\"LATE\", true(),\"OK\") | sort - status, - lag_min | table dc partner naming_context transport status last_success last_attempt lag_min last_result",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Failed replication events by DC",
      "options": {
        "query": "`adx_repl_data` | where Result!=\"0\" | timechart span=1h count by host",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Replication-related events over time",
      "options": {
        "query": "`adx_ds_events` EventCode IN (1308,1311,1388,1566,1865,1925,1988,2042,2087,2088,2095,2213,4012) | timechart count by EventCode",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "Directory Service / DFSR replication events",
      "options": {
        "query": "`adx_ds_events` EventCode IN (1308,1311,1388,1566,1865,1925,1988,2042,2087,2088,2095,2213,4012) | rename EventCode as event_id | lookup adx_replication_events event_id OUTPUT description severity | eval dc=coalesce(Computer, ComputerName, host), message=substr(coalesce(Message, _raw),1,300) | sort - _time | table _time dc event_id severity description message",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "Replication errors by DC and event",
      "options": {
        "query": "`adx_ds_events` EventCode IN (1308,1311,1388,1566,1865,1925,1988,2042,2087,2088,2095,2213,4012) | rename EventCode as event_id | lookup adx_replication_events event_id OUTPUT description | eval dc=coalesce(Computer, ComputerName, host) | stats count, latest(_time) as last by dc event_id description | eval last=strftime(last,\"%Y-%m-%d %H:%M\") | sort - count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "Security 4932/4933: replica sync start/end",
      "options": {
        "query": "`adx_security_events` (EventCode=4932 OR EventCode=4933) | eval dc=coalesce(Computer, ComputerName, host), status_code=coalesce(Status_Code, StatusCode, Status), naming_context=coalesce(Naming_Context, NamingContext), source_dra=coalesce(Source_DRA, SourceDRA) | stats count, sum(eval(if(EventCode=4933 AND status_code!=\"0\",1,0))) as failed_syncs by dc naming_context | sort - failed_syncs",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_13": {
      "type": "ds.search",
      "name": "Kerberos clock-skew failures (event 4771, code 0x25) - time sync",
      "options": {
        "query": "`adx_security_events` EventCode=4771 (Failure_Code=0x25 OR Result_Code=0x25) | eval client=coalesce(IpAddress, Client_Address, src_ip), user=coalesce(TargetUserName, Account_Name) | stats count, latest(_time) as last by client user | eval last=strftime(last,\"%Y-%m-%d %H:%M\") | sort - count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {
      "width": 1440,
      "height": 1820,
      "display": "auto-scale"
    },
    "structure": [
      {
        "item": "viz_1",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 240,
          "h": 130
        }
      },
      {
        "item": "viz_2",
        "type": "block",
        "position": {
          "x": 240,
          "y": 0,
          "w": 240,
          "h": 130
        }
      },
      {
        "item": "viz_3",
        "type": "block",
        "position": {
          "x": 480,
          "y": 0,
          "w": 240,
          "h": 130
        }
      },
      {
        "item": "viz_4",
        "type": "block",
        "position": {
          "x": 720,
          "y": 0,
          "w": 240,
          "h": 130
        }
      },
      {
        "item": "viz_5",
        "type": "block",
        "position": {
          "x": 960,
          "y": 0,
          "w": 240,
          "h": 130
        }
      },
      {
        "item": "viz_6",
        "type": "block",
        "position": {
          "x": 1200,
          "y": 0,
          "w": 240,
          "h": 130
        }
      },
      {
        "item": "viz_7",
        "type": "block",
        "position": {
          "x": 0,
          "y": 130,
          "w": 1440,
          "h": 516
        }
      },
      {
        "item": "viz_8",
        "type": "block",
        "position": {
          "x": 0,
          "y": 646,
          "w": 720,
          "h": 340
        }
      },
      {
        "item": "viz_9",
        "type": "block",
        "position": {
          "x": 720,
          "y": 646,
          "w": 720,
          "h": 340
        }
      },
      {
        "item": "viz_10",
        "type": "block",
        "position": {
          "x": 0,
          "y": 986,
          "w": 720,
          "h": 450
        }
      },
      {
        "item": "viz_11",
        "type": "block",
        "position": {
          "x": 720,
          "y": 986,
          "w": 720,
          "h": 450
        }
      },
      {
        "item": "viz_12",
        "type": "block",
        "position": {
          "x": 0,
          "y": 1436,
          "w": 720,
          "h": 384
        }
      },
      {
        "item": "viz_13",
        "type": "block",
        "position": {
          "x": 720,
          "y": 1436,
          "w": 720,
          "h": 384
        }
      }
    ],
    "globalInputs": [
      "input_global_trp"
    ]
  }
}
